const VENDOR_QUOTE_ID = "1uBuPucl5UvebEX4SZfZ";
const LAST_PROCESSED_ID = "rwUHPHY1y1gOkK8xxrU6";
const QUOTES_COMPLETE_ID = "4p6KBFM8K8ljYiw5Awwx";

const opp = $json.opportunity || $json;
const customFields = opp.customFields || [];

function fieldById(id) {
  return customFields.find(f => f.id === id) || null;
}

const vendorQuoteField = fieldById(VENDOR_QUOTE_ID);
const files = (vendorQuoteField?.fieldValueFiles || vendorQuoteField?.fieldValue || []).filter(f => !f.deleted);

const lastProcessedField = fieldById(LAST_PROCESSED_ID);
const lastProcessedValue = lastProcessedField ? (lastProcessedField.value ?? lastProcessedField.fieldValue ?? null) : null;

// Identify the current file set by its URLs -- each GHL upload gets a unique
// URL (embeds a per-file UUID), so this string changes iff the actual file(s)
// change. Sorted so array reordering alone can't register as "different".
const currentFileIdentifier = files.map(f => f.url).sort().join('|');

const hasFiles = files.length > 0;
const fileAlreadyProcessed = hasFiles && Boolean(lastProcessedValue) && currentFileIdentifier === lastProcessedValue;

let skipReason = null;
if (!hasFiles) skipReason = 'no_vendor_quote_files';
else if (fileAlreadyProcessed) skipReason = 'file_already_processed';

// "Quotes Complete" is a single-option checkbox (option label "Complete").
// GHL has been observed returning a custom field's value under different
// keys depending on the API path (fieldValue, fieldValueString, or value) --
// read all three defensively rather than assuming one shape.
const quotesCompleteField = fieldById(QUOTES_COMPLETE_ID);
const rawQuotesComplete = quotesCompleteField
  ? (quotesCompleteField.fieldValue ?? quotesCompleteField.fieldValueString ?? quotesCompleteField.value ?? null)
  : null;
const quotesComplete = Array.isArray(rawQuotesComplete)
  ? rawQuotesComplete.some(v => String(v).toLowerCase().includes('complete'))
  : typeof rawQuotesComplete === 'boolean'
    ? rawQuotesComplete
    : typeof rawQuotesComplete === 'string'
      ? ['true', 'yes', 'complete'].includes(rawQuotesComplete.toLowerCase())
      : false;

return [{ json: {
  opportunityId: opp.id,
  contactId: opp.contactId,
  shouldProceed: hasFiles && !fileAlreadyProcessed,
  skipReason,
  fileCount: files.length,
  files: files.map(f => ({ name: f.meta?.name, url: f.url, size: f.meta?.size, mimetype: f.meta?.mimetype })),
  currentFileIdentifier,
  quotesComplete,
} }];

const ROOF_TYPE_ID = "ooxcklKOKGrDCRunZnh3";

const presence = $('Code – Presence & Idempotency Check').first().json;
const contact = $json.contact || $json;
const customFields = contact.customFields || [];
const roofTypeField = customFields.find(f => f.id === ROOF_TYPE_ID) || null;
const rawRoofType = roofTypeField ? (roofTypeField.value ?? roofTypeField.fieldValue ?? null) : null;

// Values seen live in production are inconsistent in format (e.g. "standing_seam"
// vs "Standing Seam Steel"), so normalize before matching rather than relying on
// an exact string.
const normalized = (rawRoofType || '').toLowerCase().replace(/[^a-z]/g, '');
const minExpectedFileCount = normalized.includes('stonecoat') ? 2 : 1;
// A checked "Quotes Complete" box means the vendor deliberately combined
// materials and labor into a single quote document instead of the usual
// per-vendor files -- one file is enough regardless of roof type.
const expectedFileCount = presence.quotesComplete ? 1 : minExpectedFileCount;
const actualFileCount = presence.fileCount;
const complete = actualFileCount === expectedFileCount;

return [{ json: {
  opportunityId: presence.opportunityId,
  contactId: presence.contactId,
  files: presence.files,
  rawRoofType,
  quotesComplete: presence.quotesComplete,
  expectedFileCount,
  actualFileCount,
  complete,
} }];

const checked = $('Code – Check Claude Response').first().json;
const raw = checked.responseBody;

const textBlock = raw.content?.find(b => b.type === 'text');
if (!textBlock) throw new Error('No text block in Claude response: ' + JSON.stringify(raw));

const cleaned = textBlock.text.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Failed to parse Claude JSON: ' + cleaned);
}

return [{ json: {
  opportunityId: checked.opportunityId,
  contactId: checked.contactId,
  scopeOfWork: parsed.scope_of_work ?? '',
  vendorCost: parsed.vendor_cost ?? null,
  extractionNotes: parsed.extraction_notes ?? 'None',
} }];

// Turn the files array (1 item) into N items (one per file), each
// carrying the URL to fetch as binary via a real HTTP Request node --
// n8n's binary data model already base64-encodes correctly, unlike
// manually buffering inside a Code node (which corrupted the bytes).
const files = $json.files;
return files.map((f, i) => ({ json: {
  opportunityId: $json.opportunityId,
  contactId: $json.contactId,
  fileIndex: i,
  fileName: f.name,
  fileUrl: f.url,
} }));

const SYSTEM_PROMPT = `You are a contract-drafting assistant for Metroplex Metal Roofs, a metal roofing company serving DFW homeowners. You will be given one or two vendor quote PDF(s) for a single roofing job (two PDFs occur only for stone-coated steel jobs, where the underlayment/decking and the panels are quoted separately by different suppliers; every other roof type has exactly one PDF, which may combine materials and labor into a single document). Extract the following and return ONLY a valid JSON object with no preamble, no markdown, no backticks. The JSON must have exactly these keys:
- scope_of_work: a clear, concise description of the materials and system covered by the quote(s), written for a customer-facing contract. Do not include vendor pricing or cost breakdowns.
- vendor_cost: the total dollar amount for the job, as a plain number with no currency symbol or commas. If a document states its own combined/grand total, use that stated total for that document -- do NOT also add up that same document's line items, since the line items already make up the stated total and adding both double-counts the cost. Only sum line items yourself when a document has no clearly stated total. When two separate quote documents are attached (stone-coated steel jobs), add each document's total (stated or summed) together.
- extraction_notes: any ambiguity, missing pricing, or issue encountered while reading the document(s), or "None" if everything was clear.`;

const items = $input.all();
const first = items[0].json;

const content = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryKey = Object.keys(item.binary || {})[0];
  let buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);
  // GHL's file-serving URL for Opportunity FILE_UPLOAD fields prepends
  // ~76 bytes of internal object metadata before the real PDF bytes
  // (confirmed live: a protobuf-looking hash+UUID header ahead of the
  // %PDF- marker). Trim anything before the actual PDF header rather
  // than trusting byte 0, since the prefix length isn''''t guaranteed.
  const pdfStart = buffer.indexOf('%PDF');
  if (pdfStart > 0) buffer = buffer.subarray(pdfStart);
  else if (pdfStart === -1) throw new Error('No %PDF marker found in fetched file: ' + item.json.fileName);
  content.push({ type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: buffer.toString('base64') } });
}
content.push({ type: 'text', text: 'Extract the scope of work and total vendor cost from the attached vendor quote(s) as instructed.' });

return [{ json: {
  opportunityId: first.opportunityId,
  contactId: first.contactId,
  requestBody: {
    model: 'claude-sonnet-5',
    max_tokens: 2048,
    system: SYSTEM_PROMPT,
    messages: [{ role: 'user', content }],
  },
} }];

const COUNTER_NAME = "Job Number Counter";
const values = $json.customValues || [];
const counter = values.find(v => v.name === COUNTER_NAME) || null;

const now = new Date();
const yy = String(now.getFullYear()).slice(-2);
const mm = String(now.getMonth() + 1).padStart(2, '0');
const currentYYMM = yy + mm;

function computeNext(storedValue) {
  let seq = 1;
  if (storedValue) {
    const [storedYYMM, storedSeqStr] = storedValue.split('-');
    if (storedYYMM === currentYYMM) {
      seq = parseInt(storedSeqStr, 10) + 1;
    }
  }
  const newStoredValue = `${currentYYMM}-${String(seq).padStart(3, '0')}`;
  const jobNumber = `${currentYYMM}${String(seq).padStart(3, '0')}`;
  return { newStoredValue, jobNumber };
}

const readValue = counter ? counter.value : null;
const candidate = computeNext(readValue);

let prior;
try {
  prior = $('Code – Prepare Job Number Retry').first().json;
} catch (e) {
  prior = $('Code – Init Job Number Attempt').first().json;
}

return [{ json: {
  counterId: counter ? counter.id : null,
  readValue,
  candidateNewStoredValue: candidate.newStoredValue,
  candidateJobNumber: candidate.jobNumber,
  attempt: prior.attempt,
  maxAttempts: prior.maxAttempts,
} }];

const COUNTER_NAME = "Job Number Counter";
const compute = $('Code – Compute Job Number Candidate').first().json;
const values = $json.customValues || [];
const counter = values.find(v => v.name === COUNTER_NAME) || null;
const verifyReadValue = counter ? counter.value : null;

const collisionDetected = verifyReadValue !== compute.readValue;

return [{ json: {
  counterId: counter ? counter.id : compute.counterId,
  finalStoredValue: compute.candidateNewStoredValue,
  finalJobNumber: compute.candidateJobNumber,
  collisionDetected,
  attempt: compute.attempt,
  maxAttempts: compute.maxAttempts,
} }];

const prev = $json;
return [{ json: {
  attempt: prev.attempt + 1,
  maxAttempts: prev.maxAttempts,
  delayMs: Math.floor(Math.random() * 250) + 50,
} }];

const extraction = $('Code – Parse Claude Response').first().json;
const jn = $('Code – Check Job Number Collision').first().json;
const presence = $('Code – Presence & Idempotency Check').first().json;

return [{ json: {
  opportunityId: extraction.opportunityId,
  contactId: extraction.contactId,
  scopeOfWork: extraction.scopeOfWork,
  vendorCost: extraction.vendorCost,
  jobNumber: jn.finalJobNumber,
  fileIdentifier: presence.currentFileIdentifier,
