const JOB_NUMBER_ID = "CWBkt6xFQjdU97R5bKUC";
const prep = $('Code – Prepare Opportunity Write-Back').first().json;
const opportunities = $json.opportunities || [];

const matches = opportunities.filter(opp => {
  if (opp.id === prep.opportunityId) return false;
